-- 131_seed_cost_turn_regression_monitor_metric.sql
-- Evals proposal P2 (agent-fs thoughts/c06cca59-.../research/2026-08-11-evals-where-we-are-and-what-to-do.md):
-- cost & turn-count regression monitor over session_costs. No new tables, no new spend --
-- a config-driven metrics dashboard (same mechanism as 091's swarm-operations-overview)
-- whose widgets recompute rolling medians live on every view/refresh.
--
-- Per (agent x model x taskType): rolling median totalCostUsd / numTurns / durationMs for
-- a "current" window vs the immediately preceding "baseline" window, both from session_costs.
-- A group is flagged 'regression' when any of the three medians shifts by >= thresholdPct
-- vs baseline (all four thresholds are dashboard variables, editable without a migration).
-- 'insufficient-data' when either window has fewer than minSamples sessions for that group.
--
-- Caveats encoded directly in the widget description (see also shared memory
-- harness-migration-confounds-cost-analysis-2026-07-28 and
-- telemetry-token-cost-schema-and-gaps-2026-07-29):
--   * numTurns is Claude-only -- Codex (and other harnesses without a real turn count)
--     always report numTurns=1, so turnsDeltaPct reads ~0 for those rows and is not a
--     meaningful regression signal there. Cost and duration remain comparable everywhere.
--   * Grouping by model keeps cost comparisons within a single harness/pricing family, so a
--     harness migration (e.g. claude -> codex on the same schedule) shows up as two separate
--     groups rather than a false step-change in one group's trend.

INSERT OR IGNORE INTO metrics (agentId, slug, title, description, definition)
VALUES (
  'system',
  'cost-turn-regression-monitor',
  'Cost & turn regression monitor',
  'Per agent x model x taskType rolling median cost/turns/duration, current window vs baseline, flagged on a sustained shift. Evals proposal P2.',
  '{"version":1,"refreshSeconds":3600,"layout":{"columns":1},"variables":[{"key":"currentWindowDays","label":"Current window (days)","type":"number","defaultValue":7},{"key":"baselineWindowDays","label":"Baseline window length (days, ending where the current window starts)","type":"number","defaultValue":30},{"key":"minSamples","label":"Minimum sessions per window to evaluate","type":"number","defaultValue":5},{"key":"thresholdPct","label":"Flag threshold (% shift vs baseline median)","type":"number","defaultValue":40}],"widgets":[{"id":"regression-count","title":"Groups flagged for regression","description":"Count of (agent x model x taskType) groups whose current-window median cost, turn count, or duration shifted by >= the threshold vs the baseline window.","query":{"sql":"WITH params AS (\n  SELECT ? AS currentWindowDays, ? AS baselineWindowDays, ? AS minSamples, ? AS thresholdPct\n),\nbounds AS (\n  SELECT\n    datetime(''now'', ''-'' || (SELECT currentWindowDays FROM params) || '' days'') AS currentStart,\n    datetime(''now'', ''-'' || (SELECT currentWindowDays + baselineWindowDays FROM params) || '' days'') AS baselineStart\n),\nbase AS (\n  SELECT\n    sc.agentId AS agentId,\n    sc.model AS model,\n    COALESCE(t.taskType, ''unspecified'') AS taskType,\n    sc.totalCostUsd AS totalCostUsd,\n    sc.numTurns AS numTurns,\n    sc.durationMs AS durationMs,\n    CASE\n      WHEN sc.createdAt >= (SELECT currentStart FROM bounds) THEN ''current''\n      WHEN sc.createdAt >= (SELECT baselineStart FROM bounds) THEN ''baseline''\n    END AS windowLabel\n  FROM session_costs sc\n  LEFT JOIN agent_tasks t ON t.id = sc.taskId\n  WHERE sc.createdAt >= (SELECT baselineStart FROM bounds)\n),\nscoped AS (\n  SELECT * FROM base WHERE windowLabel IS NOT NULL\n),\ncost_ranked AS (\n  SELECT agentId, model, taskType, windowLabel, totalCostUsd,\n    ROW_NUMBER() OVER (PARTITION BY agentId, model, taskType, windowLabel ORDER BY totalCostUsd) AS rn,\n    COUNT(*) OVER (PARTITION BY agentId, model, taskType, windowLabel) AS cnt\n  FROM scoped\n),\ncost_median AS (\n  SELECT agentId, model, taskType, windowLabel, AVG(totalCostUsd) AS medianCost, MAX(cnt) AS n\n  FROM cost_ranked\n  WHERE rn IN ((cnt + 1) / 2, (cnt + 2) / 2)\n  GROUP BY agentId, model, taskType, windowLabel\n),\nturns_ranked AS (\n  SELECT agentId, model, taskType, windowLabel, numTurns,\n    ROW_NUMBER() OVER (PARTITION BY agentId, model, taskType, windowLabel ORDER BY numTurns) AS rn,\n    COUNT(*) OVER (PARTITION BY agentId, model, taskType, windowLabel) AS cnt\n  FROM scoped\n  WHERE numTurns IS NOT NULL\n),\nturns_median AS (\n  SELECT agentId, model, taskType, windowLabel, AVG(numTurns) AS medianTurns, MAX(cnt) AS n\n  FROM turns_ranked\n  WHERE rn IN ((cnt + 1) / 2, (cnt + 2) / 2)\n  GROUP BY agentId, model, taskType, windowLabel\n),\nduration_ranked AS (\n  SELECT agentId, model, taskType, windowLabel, durationMs,\n    ROW_NUMBER() OVER (PARTITION BY agentId, model, taskType, windowLabel ORDER BY durationMs) AS rn,\n    COUNT(*) OVER (PARTITION BY agentId, model, taskType, windowLabel) AS cnt\n  FROM scoped\n),\nduration_median AS (\n  SELECT agentId, model, taskType, windowLabel, AVG(durationMs) AS medianDuration, MAX(cnt) AS n\n  FROM duration_ranked\n  WHERE rn IN ((cnt + 1) / 2, (cnt + 2) / 2)\n  GROUP BY agentId, model, taskType, windowLabel\n),\ncost_pivot AS (\n  SELECT agentId, model, taskType,\n    MAX(CASE WHEN windowLabel = ''current'' THEN medianCost END) AS costCurrent,\n    MAX(CASE WHEN windowLabel = ''baseline'' THEN medianCost END) AS costBaseline,\n    MAX(CASE WHEN windowLabel = ''current'' THEN n END) AS nCostCurrent,\n    MAX(CASE WHEN windowLabel = ''baseline'' THEN n END) AS nCostBaseline\n  FROM cost_median\n  GROUP BY agentId, model, taskType\n),\nturns_pivot AS (\n  SELECT agentId, model, taskType,\n    MAX(CASE WHEN windowLabel = ''current'' THEN medianTurns END) AS turnsCurrent,\n    MAX(CASE WHEN windowLabel = ''baseline'' THEN medianTurns END) AS turnsBaseline\n  FROM turns_median\n  GROUP BY agentId, model, taskType\n),\nduration_pivot AS (\n  SELECT agentId, model, taskType,\n    MAX(CASE WHEN windowLabel = ''current'' THEN medianDuration END) AS durationCurrent,\n    MAX(CASE WHEN windowLabel = ''baseline'' THEN medianDuration END) AS durationBaseline\n  FROM duration_median\n  GROUP BY agentId, model, taskType\n),\njoined AS (\n  SELECT\n    cp.agentId AS agentId,\n    cp.model AS model,\n    cp.taskType AS taskType,\n    cp.costCurrent, cp.costBaseline, cp.nCostCurrent, cp.nCostBaseline,\n    tp.turnsCurrent, tp.turnsBaseline,\n    dp.durationCurrent, dp.durationBaseline\n  FROM cost_pivot cp\n  LEFT JOIN turns_pivot tp ON tp.agentId = cp.agentId AND tp.model = cp.model AND tp.taskType = cp.taskType\n  LEFT JOIN duration_pivot dp ON dp.agentId = cp.agentId AND dp.model = cp.model AND dp.taskType = cp.taskType\n),\nflagged AS (\n  SELECT\n    j.*,\n    CASE WHEN j.costBaseline > 0 THEN (j.costCurrent - j.costBaseline) * 100.0 / j.costBaseline END AS costDeltaPct,\n    CASE WHEN j.turnsBaseline > 0 THEN (j.turnsCurrent - j.turnsBaseline) * 100.0 / j.turnsBaseline END AS turnsDeltaPct,\n    CASE WHEN j.durationBaseline > 0 THEN (j.durationCurrent - j.durationBaseline) * 100.0 / j.durationBaseline END AS durationDeltaPct,\n    CASE\n      WHEN COALESCE(j.nCostCurrent, 0) < (SELECT minSamples FROM params)\n        OR COALESCE(j.nCostBaseline, 0) < (SELECT minSamples FROM params)\n        THEN ''insufficient-data''\n      WHEN ABS(COALESCE((j.costCurrent - j.costBaseline) * 100.0 / NULLIF(j.costBaseline, 0), 0)) >= (SELECT thresholdPct FROM params)\n        OR ABS(COALESCE((j.turnsCurrent - j.turnsBaseline) * 100.0 / NULLIF(j.turnsBaseline, 0), 0)) >= (SELECT thresholdPct FROM params)\n        OR ABS(COALESCE((j.durationCurrent - j.durationBaseline) * 100.0 / NULLIF(j.durationBaseline, 0), 0)) >= (SELECT thresholdPct FROM params)\n        THEN ''regression''\n      ELSE ''ok''\n    END AS status\n  FROM joined j\n)\nSELECT COUNT(*) AS regressionCount FROM flagged WHERE status = ''regression''","params":["{{currentWindowDays}}","{{baselineWindowDays}}","{{minSamples}}","{{thresholdPct}}"],"maxRows":1},"viz":{"type":"stat","value":"regressionCount","format":"integer"},"colSpan":1},{"id":"cost-turn-duration-regression","title":"Cost / turn-count / duration regression by agent x model x taskType","description":"Rolling median totalCostUsd, numTurns, durationMs per group for the current window vs the immediately preceding baseline window, from session_costs. numTurns is Claude-only (harnesses that don''t report a real turn count, e.g. Codex, always report 1, so their turnsDeltaPct will read ~0 and is not a meaningful signal for those rows). status = ''insufficient-data'' when either window has fewer than minSamples sessions in that group.","query":{"sql":"WITH params AS (\n  SELECT ? AS currentWindowDays, ? AS baselineWindowDays, ? AS minSamples, ? AS thresholdPct\n),\nbounds AS (\n  SELECT\n    datetime(''now'', ''-'' || (SELECT currentWindowDays FROM params) || '' days'') AS currentStart,\n    datetime(''now'', ''-'' || (SELECT currentWindowDays + baselineWindowDays FROM params) || '' days'') AS baselineStart\n),\nbase AS (\n  SELECT\n    sc.agentId AS agentId,\n    sc.model AS model,\n    COALESCE(t.taskType, ''unspecified'') AS taskType,\n    sc.totalCostUsd AS totalCostUsd,\n    sc.numTurns AS numTurns,\n    sc.durationMs AS durationMs,\n    CASE\n      WHEN sc.createdAt >= (SELECT currentStart FROM bounds) THEN ''current''\n      WHEN sc.createdAt >= (SELECT baselineStart FROM bounds) THEN ''baseline''\n    END AS windowLabel\n  FROM session_costs sc\n  LEFT JOIN agent_tasks t ON t.id = sc.taskId\n  WHERE sc.createdAt >= (SELECT baselineStart FROM bounds)\n),\nscoped AS (\n  SELECT * FROM base WHERE windowLabel IS NOT NULL\n),\ncost_ranked AS (\n  SELECT agentId, model, taskType, windowLabel, totalCostUsd,\n    ROW_NUMBER() OVER (PARTITION BY agentId, model, taskType, windowLabel ORDER BY totalCostUsd) AS rn,\n    COUNT(*) OVER (PARTITION BY agentId, model, taskType, windowLabel) AS cnt\n  FROM scoped\n),\ncost_median AS (\n  SELECT agentId, model, taskType, windowLabel, AVG(totalCostUsd) AS medianCost, MAX(cnt) AS n\n  FROM cost_ranked\n  WHERE rn IN ((cnt + 1) / 2, (cnt + 2) / 2)\n  GROUP BY agentId, model, taskType, windowLabel\n),\nturns_ranked AS (\n  SELECT agentId, model, taskType, windowLabel, numTurns,\n    ROW_NUMBER() OVER (PARTITION BY agentId, model, taskType, windowLabel ORDER BY numTurns) AS rn,\n    COUNT(*) OVER (PARTITION BY agentId, model, taskType, windowLabel) AS cnt\n  FROM scoped\n  WHERE numTurns IS NOT NULL\n),\nturns_median AS (\n  SELECT agentId, model, taskType, windowLabel, AVG(numTurns) AS medianTurns, MAX(cnt) AS n\n  FROM turns_ranked\n  WHERE rn IN ((cnt + 1) / 2, (cnt + 2) / 2)\n  GROUP BY agentId, model, taskType, windowLabel\n),\nduration_ranked AS (\n  SELECT agentId, model, taskType, windowLabel, durationMs,\n    ROW_NUMBER() OVER (PARTITION BY agentId, model, taskType, windowLabel ORDER BY durationMs) AS rn,\n    COUNT(*) OVER (PARTITION BY agentId, model, taskType, windowLabel) AS cnt\n  FROM scoped\n),\nduration_median AS (\n  SELECT agentId, model, taskType, windowLabel, AVG(durationMs) AS medianDuration, MAX(cnt) AS n\n  FROM duration_ranked\n  WHERE rn IN ((cnt + 1) / 2, (cnt + 2) / 2)\n  GROUP BY agentId, model, taskType, windowLabel\n),\ncost_pivot AS (\n  SELECT agentId, model, taskType,\n    MAX(CASE WHEN windowLabel = ''current'' THEN medianCost END) AS costCurrent,\n    MAX(CASE WHEN windowLabel = ''baseline'' THEN medianCost END) AS costBaseline,\n    MAX(CASE WHEN windowLabel = ''current'' THEN n END) AS nCostCurrent,\n    MAX(CASE WHEN windowLabel = ''baseline'' THEN n END) AS nCostBaseline\n  FROM cost_median\n  GROUP BY agentId, model, taskType\n),\nturns_pivot AS (\n  SELECT agentId, model, taskType,\n    MAX(CASE WHEN windowLabel = ''current'' THEN medianTurns END) AS turnsCurrent,\n    MAX(CASE WHEN windowLabel = ''baseline'' THEN medianTurns END) AS turnsBaseline\n  FROM turns_median\n  GROUP BY agentId, model, taskType\n),\nduration_pivot AS (\n  SELECT agentId, model, taskType,\n    MAX(CASE WHEN windowLabel = ''current'' THEN medianDuration END) AS durationCurrent,\n    MAX(CASE WHEN windowLabel = ''baseline'' THEN medianDuration END) AS durationBaseline\n  FROM duration_median\n  GROUP BY agentId, model, taskType\n),\njoined AS (\n  SELECT\n    cp.agentId AS agentId,\n    cp.model AS model,\n    cp.taskType AS taskType,\n    cp.costCurrent, cp.costBaseline, cp.nCostCurrent, cp.nCostBaseline,\n    tp.turnsCurrent, tp.turnsBaseline,\n    dp.durationCurrent, dp.durationBaseline\n  FROM cost_pivot cp\n  LEFT JOIN turns_pivot tp ON tp.agentId = cp.agentId AND tp.model = cp.model AND tp.taskType = cp.taskType\n  LEFT JOIN duration_pivot dp ON dp.agentId = cp.agentId AND dp.model = cp.model AND dp.taskType = cp.taskType\n),\nflagged AS (\n  SELECT\n    j.*,\n    CASE WHEN j.costBaseline > 0 THEN (j.costCurrent - j.costBaseline) * 100.0 / j.costBaseline END AS costDeltaPct,\n    CASE WHEN j.turnsBaseline > 0 THEN (j.turnsCurrent - j.turnsBaseline) * 100.0 / j.turnsBaseline END AS turnsDeltaPct,\n    CASE WHEN j.durationBaseline > 0 THEN (j.durationCurrent - j.durationBaseline) * 100.0 / j.durationBaseline END AS durationDeltaPct,\n    CASE\n      WHEN COALESCE(j.nCostCurrent, 0) < (SELECT minSamples FROM params)\n        OR COALESCE(j.nCostBaseline, 0) < (SELECT minSamples FROM params)\n        THEN ''insufficient-data''\n      WHEN ABS(COALESCE((j.costCurrent - j.costBaseline) * 100.0 / NULLIF(j.costBaseline, 0), 0)) >= (SELECT thresholdPct FROM params)\n        OR ABS(COALESCE((j.turnsCurrent - j.turnsBaseline) * 100.0 / NULLIF(j.turnsBaseline, 0), 0)) >= (SELECT thresholdPct FROM params)\n        OR ABS(COALESCE((j.durationCurrent - j.durationBaseline) * 100.0 / NULLIF(j.durationBaseline, 0), 0)) >= (SELECT thresholdPct FROM params)\n        THEN ''regression''\n      ELSE ''ok''\n    END AS status\n  FROM joined j\n)\nSELECT\n  COALESCE(ag.name, f.agentId) AS agent,\n  f.model AS model,\n  f.taskType AS taskType,\n  ROUND(f.costCurrent, 4) AS costCurrent,\n  ROUND(f.costBaseline, 4) AS costBaseline,\n  ROUND(f.costDeltaPct, 1) AS costDeltaPct,\n  ROUND(f.turnsCurrent, 1) AS turnsCurrent,\n  ROUND(f.turnsBaseline, 1) AS turnsBaseline,\n  ROUND(f.turnsDeltaPct, 1) AS turnsDeltaPct,\n  ROUND(f.durationCurrent, 0) AS durationCurrentMs,\n  ROUND(f.durationBaseline, 0) AS durationBaselineMs,\n  ROUND(f.durationDeltaPct, 1) AS durationDeltaPct,\n  f.nCostCurrent AS sampleCountCurrent,\n  f.nCostBaseline AS sampleCountBaseline,\n  f.status AS status\nFROM flagged f\nLEFT JOIN agents ag ON ag.id = f.agentId\nORDER BY\n  CASE f.status WHEN ''regression'' THEN 0 WHEN ''ok'' THEN 1 ELSE 2 END,\n  ABS(COALESCE(f.costDeltaPct, 0)) DESC","params":["{{currentWindowDays}}","{{baselineWindowDays}}","{{minSamples}}","{{thresholdPct}}"],"maxRows":200},"viz":{"type":"table","columns":[{"key":"agent","label":"Agent"},{"key":"model","label":"Model"},{"key":"taskType","label":"Task type"},{"key":"costCurrent","label":"Cost/session (current)","format":"currency"},{"key":"costBaseline","label":"Cost/session (baseline)","format":"currency"},{"key":"costDeltaPct","label":"Cost delta","format":"percent"},{"key":"turnsCurrent","label":"Turns (current)","format":"number"},{"key":"turnsBaseline","label":"Turns (baseline)","format":"number"},{"key":"turnsDeltaPct","label":"Turns delta","format":"percent"},{"key":"durationCurrentMs","label":"Duration ms (current)","format":"number"},{"key":"durationBaselineMs","label":"Duration ms (baseline)","format":"number"},{"key":"durationDeltaPct","label":"Duration delta","format":"percent"},{"key":"sampleCountCurrent","label":"N (current)","format":"integer"},{"key":"sampleCountBaseline","label":"N (baseline)","format":"integer"},{"key":"status","label":"Status"}]},"colSpan":1}]}'
);

